    /// Key-value pairs to specify advanced configuration options. The fol- lowing key-value pairs are supported: o "rest.action.multi.allow_explicit_index": "true" | "false" - Note the use of a string rather than a boolean. Specifies whether ex- plicit references to indexes are allowed inside the body of HTTP requests. If you want to configure access policies for domain sub-resources, such as specific indexes and domain APIs, you must disable this property. Default is true. o "indices.fielddata.cache.size": "80" - Note the use of a string rather than a boolean. Specifies the percentage of heap space al- located to field data. Default is unbounded. o "indices.query.bool.max_clause_count": "1024" - Note the use of a string rather than a boolean. Specifies the maximum number of clauses allowed in a Lucene boolean query. Default is 1,024. Queries with more than the permitted number of clauses result in a TooManyClauses error. For more information, see Advanced cluster parameters . key -&gt; (string) value -&gt; (string) Shorthand Syntax: KeyName1=string,KeyName2=string JSON Syntax: {"string": "string" ...}
    /// </summary>
    [CliOption("--advanced-options", GroupValues = true)]
    public IReadOnlyList<KeyValue>? AdvancedOptions { get; set; }

    /// <summary>
    /// Identity and Access Management (IAM) access policy as a JSON-format- ted string. Constraints: o min: 0 o max: 102400 o pattern: .*
    /// </summary>
    [CliOption("--access-policies")]
    public string? AccessPolicies { get; set; }

    /// <summary>
    /// Specify either dual stack or IPv4 as your IP address type. Dual stack allows you to share domain resources across IPv4 and IPv6 ad- dress types, and is the recommended option. If your IP address type is currently set to dual stack, you can't change it. Possible values: o ipv4 o dualstack
    /// </summary>
    [CliOption("--ip-address-type")]
    public AwsOpensearchUpdateDomainConfigIpAddressType? IpAddressType { get; set; }

    /// <summary>
    /// Options to publish OpenSearch logs to Amazon CloudWatch Logs. key -&gt; (string) The type of log file. Can be one of the following: o INDEX_SLOW_LOGS - Index slow logs contain insert requests that took more time than the configured index query log threshold to execute. o SEARCH_SLOW_LOGS - Search slow logs contain search queries that took more time than the configured search query log threshold to execute. o ES_APPLICATION_LOGS - OpenSearch application logs contain in- formation about errors and warnings raised during the opera- tion of the service and can be useful for troubleshooting. o AUDIT_LOGS - Audit logs contain records of user requests for access to the domain. Possible values: o INDEX_SLOW_LOGS o SEARCH_SLOW_LOGS o ES_APPLICATION_LOGS o AUDIT_LOGS value -&gt; (structure) Specifies whether the Amazon OpenSearch Service domain publishes the OpenSearch application and slow logs to Amazon CloudWatch. For more information, see Monitoring OpenSearch logs with Amazon CloudWatch Logs . NOTE: After you enable log publishing, you still have to enable the collection of slow logs using the OpenSearch REST API. CloudWatchLogsLogGroupArn -&gt; (string) The Amazon Resource Name (ARN) of the CloudWatch Logs group to publish logs to. Constraints: o min: 20 o max: 2048 o pattern: .* Enabled -&gt; (boolean) Whether the log should be published. Shorthand Syntax: KeyName1={CloudWatchLogsLogGroupArn=string,Enabled=boolean},KeyName2={CloudWatchLogsLogGroupArn=string,Enabled=boolean} Where valid key names are: INDEX_SLOW_LOGS SEARCH_SLOW_LOGS ES_APPLICATION_LOGS AUDIT_LOGS JSON Syntax: {"INDEX_SLOW_LOGS"|"SEARCH_SLOW_LOGS"|"ES_APPLICATION_LOGS"|"AUDIT_LOGS": { "CloudWatchLogsLogGroupArn": "string", "Enabled": true|false } ...}
    /// </summary>
    [CliOption("--log-publishing-options", GroupValues = true)]
    public IReadOnlyList<KeyValue>? LogPublishingOptions { get; set; }

    /// <summary>
    /// Encryption at rest options for the domain. Enabled -&gt; (boolean) True to enable encryption at rest. KmsKeyId -&gt; (string) The KMS key ID. Takes the form 1a2a3a4-1a2a-3a4a-5a6a-1a2a3a4a5a6a . Constraints: o min: 1 o max: 500 o pattern: .* Shorthand Syntax: Enabled=boolean,KmsKeyId=string JSON Syntax: { "Enabled": true|false, "KmsKeyId": "string" }
    /// </summary>
    [CliOption("--encryption-at-rest-options")]
    public string? EncryptionAtRestOptions { get; set; }

    /// <summary>
    /// Additional options for the domain endpoint, such as whether to re- quire HTTPS for all traffic. EnforceHTTPS -&gt; (boolean) True to require that all traffic to the domain arrive over HTTPS. TLSSecurityPolicy -&gt; (string) Specify the TLS security policy to apply to the HTTPS endpoint of the domain. The policy can be one of the following values: o Policy-Min-TLS-1-0-2019-07: TLS security policy that supports TLS version 1.0 to TLS version 1.2 o Policy-Min-TLS-1-2-2019-07: TLS security policy that supports only TLS version 1.2 o Policy-Min-TLS-1-2-PFS-2023-10: TLS security policy that sup- ports TLS version 1.2 to TLS version 1.3 with perfect forward secrecy cipher suites o Policy-Min-TLS-1-2-RFC9151-FIPS-2024-08: TLS security policy that supports TLS version 1.3 with FIPS Possible values: o Policy-Min-TLS-1-0-2019-07 o Policy-Min-TLS-1-2-2019-07 o Policy-Min-TLS-1-2-PFS-2023-10 o Policy-Min-TLS-1-2-RFC9151-FIPS-2024-08 CustomEndpointEnabled -&gt; (boolean) Whether to enable a custom endpoint for the domain. CustomEndpoint -&gt; (string) The fully qualified URL for the custom endpoint. Constraints: o min: 1 o max: 255 o pattern: ^(((?!-)[A-Za-z0-9-]{0,62}[A-Za-z0-9])\.)+((?!-)[A-Za-z0-9-]{1,62}[A-Za-z0-9])$ CustomEndpointCertificateArn -&gt; (string) The ARN for your security certificate, managed in Amazon Web Services Certificate Manager (ACM). Constraints: o min: 20 o max: 2048 o pattern: .* Shorthand Syntax: EnforceHTTPS=boolean,TLSSecurityPolicy=string,CustomEndpointEnabled=boolean,CustomEndpoint=string,CustomEndpointCertificateArn=string JSON Syntax: { "EnforceHTTPS": true|false, "TLSSecurityPolicy": "Policy-Min-TLS-1-0-2019-07"|"Policy-Min-TLS-1-2-2019-07"|"Policy-Min-TLS-1-2-PFS-2023-10"|"Policy-Min-TLS-1-2-RFC9151-FIPS-2024-08", "CustomEndpointEnabled": true|false, "CustomEndpoint": "string", "CustomEndpointCertificateArn": "string" }
    /// </summary>
    [CliOption("--domain-endpoint-options")]
    public string? DomainEndpointOptions { get; set; }

