    /// </summary>
    [CliOption("--node-to-node-encryption-options")]
    public string? NodeToNodeEncryptionOptions { get; set; }

    /// <summary>
    /// Options for fine-grained access control. Enabled -&gt; (boolean) True to enable fine-grained access control. InternalUserDatabaseEnabled -&gt; (boolean) True to enable the internal user database. MasterUserOptions -&gt; (structure) Container for information about the master user. MasterUserARN -&gt; (string) Amazon Resource Name (ARN) for the master user. Only specify if InternalUserDatabaseEnabled is false . Constraints: o min: 20 o max: 2048 o pattern: .* MasterUserName -&gt; (string) User name for the master user. Only specify if InternalUser- DatabaseEnabled is true . Constraints: o min: 1 o max: 64 o pattern: .* MasterUserPassword -&gt; (string) Password for the master user. Only specify if InternalUser- DatabaseEnabled is true . Constraints: o min: 8 o max: 128 o pattern: .* SAMLOptions -&gt; (structure) Container for information about the SAML configuration for OpenSearch Dashboards. Enabled -&gt; (boolean) True to enable SAML authentication for a domain. Idp -&gt; (structure) The SAML Identity Provider's information. MetadataContent -&gt; (string) [required] The metadata of the SAML application, in XML format. Constraints: o min: 1 o max: 1048576 EntityId -&gt; (string) [required] The unique entity ID of the application in the SAML iden- tity provider. Constraints: o min: 8 o max: 512 MasterUserName -&gt; (string) The SAML master user name, which is stored in the domain's internal user database. Constraints: o min: 1 o max: 64 o pattern: .* MasterBackendRole -&gt; (string) The backend role that the SAML master user is mapped to. Constraints: o min: 1 o max: 256 SubjectKey -&gt; (string) Element of the SAML assertion to use for the user name. De- fault is NameID . RolesKey -&gt; (string) Element of the SAML assertion to use for backend roles. De- fault is roles . SessionTimeoutMinutes -&gt; (integer) The duration, in minutes, after which a user session becomes inactive. Acceptable values are between 1 and 1440, and the default value is 60. JWTOptions -&gt; (structure) Container for information about the JWT configuration of the Amazon OpenSearch Service. Enabled -&gt; (boolean) True to enable JWT authentication and authorization for a do- main. SubjectKey -&gt; (string) Element of the JWT assertion to use for the user name. Constraints: o min: 1 o max: 64 RolesKey -&gt; (string) Element of the JWT assertion to use for roles. Constraints: o min: 1 o max: 64 JwksUrl -&gt; (string) The URL endpoint that hosts the JSON Web Key Set (JWKS) con- taining public keys used to verify JWT signatures. Constraints: o min: 0 o max: 2048 o pattern: ^$|^https://(?!(?:10|127|169\.254|192\.168|172\.(?:1[6-9]|2[0-9]|3[01]))\.)[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*\.[a-zA-Z]{2,}(?::[0-9]{1,5})?(?:/[a-zA-Z0-9\-._~%!$&amp;'()*+,;=:'@]*(?:/[a-zA-Z0-9\-._~%!$&amp;'()*+,;=:'@]*)*)?(?:\?[a-zA-Z0-9\-._~%!$&amp;'()*+,;=:'/@?]+)?$ PublicKey -&gt; (string) Element of the JWT assertion used by the cluster to verify JWT signatures. IAMFederationOptions -&gt; (structure) Input configuration for IAM identity federation within advanced security options. Enabled -&gt; (boolean) Specifies whether IAM identity federation is enabled for the OpenSearch domain. SubjectKey -&gt; (string) The key in the SAML assertion that contains the user's sub- ject identifier. Constraints: o min: 1 o max: 64 o pattern: ^(null|[A-Za-z][A-Za-z0-9_.:/=+\-@]*)$ RolesKey -&gt; (string) The key in the SAML assertion that contains the user's role information. Constraints: o min: 1 o max: 64 o pattern: ^(null|[A-Za-z][A-Za-z0-9_.:/=+\-@]*)$ AnonymousAuthEnabled -&gt; (boolean) True to enable a 30-day migration period during which adminis- trators can create role mappings. Only necessary when enabling fine-grained access control on an existing domain . Shorthand Syntax: Enabled=boolean,InternalUserDatabaseEnabled=boolean,MasterUserOptions={MasterUserARN=string,MasterUserName=string,MasterUserPassword=string},SAMLOptions={Enabled=boolean,Idp={MetadataContent=string,EntityId=string},MasterUserName=string,MasterBackendRole=string,SubjectKey=string,RolesKey=string,SessionTimeoutMinutes=integer},JWTOptions={Enabled=boolean,SubjectKey=string,RolesKey=string,JwksUrl=string,PublicKey=string},IAMFederationOptions={Enabled=boolean,SubjectKey=string,RolesKey=string},AnonymousAuthEnabled=boolean JSON Syntax: { "Enabled": true|false, "InternalUserDatabaseEnabled": true|false, "MasterUserOptions": { "MasterUserARN": "string", "MasterUserName": "string", "MasterUserPassword": "string" }, "SAMLOptions": { "Enabled": true|false, "Idp": { "MetadataContent": "string", "EntityId": "string" }, "MasterUserName": "string", "MasterBackendRole": "string", "SubjectKey": "string", "RolesKey": "string", "SessionTimeoutMinutes": integer }, "JWTOptions": { "Enabled": true|false, "SubjectKey": "string", "RolesKey": "string", "JwksUrl": "string", "PublicKey": "string" }, "IAMFederationOptions": { "Enabled": true|false, "SubjectKey": "string", "RolesKey": "string" }, "AnonymousAuthEnabled": true|false }
    /// </summary>
    [CliOption("--advanced-security-options")]
    public string? AdvancedSecurityOptions { get; set; }

    /// <summary>
    /// Configuration settings for enabling and managing IAM Identity Cen- ter. EnabledAPIAccess -&gt; (boolean) Indicates whether IAM Identity Center is enabled for API access in Amazon OpenSearch Service. IdentityCenterInstanceARN -&gt; (string) The ARN of the IAM Identity Center instance used to create an OpenSearch UI application that uses IAM Identity Center for au- thentication. Constraints: o min: 20 o max: 2048 o pattern: ^arn:aws[a-z\\-]*:[a-z]+:[a-z0-9\\-]*:[0-9]*:[a-z0-9\\-]+\/[a-z0-9\\-]+ IdentityCenterInstanceRegion -&gt; (string) The Region of the IAM Identity Center instance. Constraints: o min: 5 o max: 30 o pattern: [a-z][a-z0-9\-]+ SubjectKey -&gt; (string) Specifies the attribute that contains the subject identifier (such as username, user ID, or email) in IAM Identity Center. Possible values: o UserName o UserId o Email RolesKey -&gt; (string) Specifies the attribute that contains the backend role identi- fier (such as group name or group ID) in IAM Identity Center. Possible values: o GroupName o GroupId Shorthand Syntax: EnabledAPIAccess=boolean,IdentityCenterInstanceARN=string,IdentityCenterInstanceRegion=string,SubjectKey=string,RolesKey=string JSON Syntax: { "EnabledAPIAccess": true|false, "IdentityCenterInstanceARN": "string", "IdentityCenterInstanceRegion": "string", "SubjectKey": "UserName"|"UserId"|"Email", "RolesKey": "GroupName"|"GroupId" }
    /// </summary>
    [CliOption("--identity-center-options")]
    public string? IdentityCenterOptions { get; set; }

    /// <summary>
    /// Options for Auto-Tune. DesiredState -&gt; (string) Whether Auto-Tune is enabled or disabled. Possible values: o ENABLED o DISABLED RollbackOnDisable -&gt; (string) When disabling Auto-Tune, specify NO_ROLLBACK to retain all prior Auto-Tune settings or DEFAULT_ROLLBACK to revert to the OpenSearch Service defaults. If you specify DEFAULT_ROLLBACK , you must include a MaintenanceSchedule in the request. Other- wise, OpenSearch Service is unable to perform the rollback. Possible values: o NO_ROLLBACK o DEFAULT_ROLLBACK MaintenanceSchedules -&gt; (list) DEPRECATED. Use off-peak window instead. A list of maintenance schedules during which Auto-Tune can de- ploy changes. Constraints: o max: 100 (structure) NOTE: This object is deprecated. Use the domain's off-peak win- dow to schedule Auto-Tune optimizations. For migration instructions, see Migrating from Auto-Tune maintenance windows . The Auto-Tune maintenance schedule. For more information, see Auto-Tune for Amazon OpenSearch Service . StartAt -&gt; (timestamp) The Epoch timestamp at which the Auto-Tune maintenance schedule starts. Duration -&gt; (structure) The duration of the maintenance schedule. For example, "Duration": {"Value": 2, "Unit": "HOURS"} . Value -&gt; (long) Integer to specify the value of a maintenance schedule duration. Constraints: o min: 1 o max: 24 Unit -&gt; (string) The unit of measurement for the duration of a mainte- nance schedule. Possible values: o HOURS CronExpressionForRecurrence -&gt; (string) A cron expression for a recurring maintenance schedule during which Auto-Tune can deploy changes. UseOffPeakWindow -&gt; (boolean) Whether to use the domain's off-peak window to deploy configura- tion changes on the domain rather than a maintenance schedule. JSON Syntax: { "DesiredState": "ENABLED"|"DISABLED", "RollbackOnDisable": "NO_ROLLBACK"|"DEFAULT_ROLLBACK", "MaintenanceSchedules": [ { "StartAt": timestamp, "Duration": { "Value": long, "Unit": "HOURS" }, "CronExpressionForRecurrence": "string" } ... ], "UseOffPeakWindow": true|false }
    /// </summary>
    [CliOption("--auto-tune-options")]
    public string? AutoTuneOptions { get; set; }

    [CliFlag("--dry-run")]
