    /// <summary>
    /// Options for all machine learning features for the specified domain. NaturalLanguageQueryGenerationOptions -&gt; (structure) Container for parameters required for natural language query generation on the specified domain. DesiredState -&gt; (string) The desired state of the natural language query generation feature. Valid values are ENABLED and DISABLED. Possible values: o ENABLED o DISABLED S3VectorsEngine -&gt; (structure) Container for parameters required to enable S3 vectors engine features on the specified domain. Enabled -&gt; (boolean) Enables S3 vectors engine features. ServerlessVectorAcceleration -&gt; (structure) Specifies whether to enable serverless vector acceleration for the domain. When enabled, provides GPU-accelerated vector search capabilities for improved performance on vector workloads. Enabled -&gt; (boolean) Specifies whether serverless vector acceleration is enabled for the domain. Shorthand Syntax: NaturalLanguageQueryGenerationOptions={DesiredState=string},S3VectorsEngine={Enabled=boolean},ServerlessVectorAcceleration={Enabled=boolean} JSON Syntax: { "NaturalLanguageQueryGenerationOptions": { "DesiredState": "ENABLED"|"DISABLED" }, "S3VectorsEngine": { "Enabled": true|false }, "ServerlessVectorAcceleration": { "Enabled": true|false } }
    /// </summary>
    [CliOption("--aiml-options")]
